Your expense tracker is below. Add what you spend, and the total, category bars and budget left update as you go. It keeps entries only while this page is open, so nothing is saved after you close it.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body{font-family:Segoe UI,Arial,sans-serif;margin:0;padding:16px;background:#f6f7f5;color:#222}
  h2{margin:0 0 12px;font-size:20px}
  .card{background:#fff;border-radius:12px;padding:14px;margin-bottom:12px;box-shadow:0 1px 3px rgba(0,0,0,.08)}
  .row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px}
  input,select{padding:8px;border:1px solid #ccc;border-radius:8px;font-size:14px;flex:1;min-width:110px}
  button{padding:8px 14px;border:0;border-radius:8px;background:#2f7d5b;color:#fff;font-size:14px;cursor:pointer}
  button.x{background:#c0392b;padding:4px 9px}
  .big{font-size:26px;font-weight:600}
  .muted{color:#666;font-size:13px}
  .bar{height:10px;border-radius:5px;background:#2f7d5b;margin-top:3px}
  .track{background:#e4e8e5;border-radius:5px}
  .item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee;font-size:14px}
  .over{color:#c0392b}
</style>
</head>
<body>
<h2>Monthly expenses</h2>

<div class="card">
  <div class="row">
    <input id="desc" type="text" placeholder="What was it for?">
    <input id="amt" type="number" min="0" placeholder="Amount (₹)">
  </div>
  <div class="row">
    <select id="cat">
      <option>Food</option><option>Rent</option><option>Travel</option>
      <option>Bills</option><option>Shopping</option><option>Health</option><option>Other</option>
    </select>
    <button onclick="add()">Add</button>
  </div>
</div>

<div class="card">
  <div class="muted">Spent this month</div>
  <div class="big" id="total">₹0</div>
  <div class="row" style="margin-top:8px">
    <input id="budget" type="number" min="0" placeholder="Monthly budget (₹)" oninput="render()">
  </div>
  <div class="muted" id="left"></div>
</div>

<div class="card">
  <div class="muted" style="margin-bottom:6px">By category</div>
  <div id="cats" class="muted">Nothing yet.</div>
</div>

<div class="card">
  <div class="muted" style="margin-bottom:6px">Entries</div>
  <div id="list" class="muted">Nothing yet.</div>
</div>

<script>
var items=[];
function inr(n){return '₹'+Math.round(n).toLocaleString('en-IN');}
function add(){
  var d=document.getElementById('desc').value.trim();
  var a=parseFloat(document.getElementById('amt').value);
  var c=document.getElementById('cat').value;
  if(!a||a<=0){return;}
  items.push({d:d||c,a:a,c:c});
  document.getElementById('desc').value='';
  document.getElementById('amt').value='';
  render();
}
function del(i){items.splice(i,1);render();}
function render(){
  var t=0,by={};
  items.forEach(function(x){t+=x.a;by[x.c]=(by[x.c]||0)+x.a;});
  document.getElementById('total').textContent=inr(t);
  var b=parseFloat(document.getElementById('budget').value);
  var l=document.getElementById('left');
  if(b>0){
    l.innerHTML=t>b?'<span class="over">Over budget by '+inr(t-b)+'</span>':inr(b-t)+' left of '+inr(b);
  }else{l.textContent='';}
  var cs=Object.keys(by).sort(function(p,q){return by[q]-by[p];});
  document.getElementById('cats').innerHTML=cs.length?cs.map(function(k){
    var p=t?by[k]/t*100:0;
    return '<div style="margin-bottom:8px;color:#222;font-size:14px"><div class="item" style="border:0;padding:0"><span>'+k+'</span><span>'+inr(by[k])+'</span></div><div class="track"><div class="bar" style="width:'+p+'%"></div></div></div>';
  }).join(''):'Nothing yet.';
  document.getElementById('list').innerHTML=items.length?items.map(function(x,i){
    return '<div class="item"><span>'+esc(x.d)+' <span class="muted">· '+x.c+'</span></span><span>'+inr(x.a)+' <button class="x" onclick="del('+i+')">×</button></span></div>';
  }).join(''):'Nothing yet.';
}
function esc(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
</script>
</body>
</html>
```
